WITH RankedPosts AS (SELECT p.Id, p.Title, p.Score, p.CreationDate, p.OwnerUserId, RANK() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.CreationDate > CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserBadges AS (SELECT u.Id AS UserId, COUNT(b.Id) AS BadgeCount, SUM(CASE WHEN b.Class = 1 THEN 1 ELSE 0 END) AS GoldBadgeCount, SUM(CASE WHEN b.Class = 2 THEN 1 ELSE 0 END) AS SilverBadgeCount, SUM(CASE WHEN b.Class = 3 THEN 1 ELSE 0 END) AS BronzeBadgeCount FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id), PostsWithCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(ct.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS ct ON ph.Comment = CAST(ct.Id AS Nullable(String)) WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT up.DisplayName AS UserDisplayName, up.Reputation, rp.Title, rp.Score, ub.BadgeCount, ub.GoldBadgeCount, ub.SilverBadgeCount, ub.BronzeBadgeCount, COALESCE(pc.CloseReasons, 'No close reasons') AS CloseReasons FROM Users AS up JOIN RankedPosts AS rp ON up.Id = rp.OwnerUserId LEFT JOIN UserBadges AS ub ON up.Id = ub.UserId LEFT JOIN PostsWithCloseReasons AS pc ON rp.Id = pc.PostId WHERE rp.PostRank = 1 AND up.Reputation > 1000 ORDER BY ub.BadgeCount DESC NULLS FIRST, rp.Score DESC NULLS FIRST LIMIT 10